package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.BasicType;
import java.io.*;
import java.lang.reflect.TypeVariable;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Unit tests for CollectionType.construct
 */
public class CollectionType_construct_TriageGen2Test {

    @Test
    public void testConstruct_WithListAndString() {
        // Arrange
        Class<?> rawType = List.class;
        JavaType elemT = BasicType.fromStringType(String.class);

        // Act
        CollectionType result = CollectionType.construct(rawType, elemT);

        // Assert
        assertNotNull("Result should not be null", result);
        assertEquals("Raw type should match", rawType, result.getRawClass());
        assertEquals("Element type should match", elemT, result.getContentType());
        // Note: Based on the provided implementation, bindings are always emptyBindings() due to 'if (true)'
        assertEquals("toString should represent the type", "List<java.lang.String>", result.toString());
    }

    @Test
    public void testConstruct_WithSetAndInteger() {
        // Arrange
        Class<?> rawType = java.util.Set.class;
        JavaType elemT = BasicType.fromStringType(Integer.class);

        // Act
        CollectionType result = CollectionType.construct(rawType, elemT);

        // Assert
        assertNotNull(result);
        assertEquals(java.util.Set.class, result.getRawClass());
        assertEquals(elemT, result.getContentType());
        assertEquals("Set<java.lang.Integer>", result.toString());
    }

    @Test
    public void testConstruct_WithGenericRawType() {
        // Arrange: Testing with a type that has type parameters
        Class<?> rawType = Collection.class;
        JavaType elemT = BasicType.fromStringType(Object.class);

        // Act
        CollectionType result = CollectionType.construct(rawType, elemT);

        // Assert
        assertNotNull(result);
        assertEquals(Collection.class, result.getRawClass());
        assertEquals(elemT, result.getContentType());
    }

    @Test
    public void testConstruct_WithCustomCollection() {
        // Arrange
        class MyCollection<T> extends java.util.ArrayList<T> {}
        Class<?> rawType = MyCollection.class;
        JavaType elemT = BasicType.fromStringType(Double.class);

        // Act
        CollectionType result = CollectionType.construct(rawType, elemT);

        // Assert
        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(elemT, result.getContentType());
        assertEquals("MyCollection<java.lang.Double>", result.toString());
    }
}
